import numpy as np,json,sys,time
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
S=json.load(open('/app/output/spec.json'))
P=np.array(S['arm']['position_m']); AX=np.array(S['arm']['axis']); EE=np.array(S['arm']['end_effector']['position_m'])
r=Robot()
def fk(q):
 T=np.eye(4)
 for p,ax,a in zip(P,AX,q):
  R=Rotation.from_rotvec(ax*a).as_matrix(); U=np.eye(4);U[:3,:3]=R;U[:3,3]=p-R@p;T=T@U
 return T

def frame(obs):
 b=obs['proprio']['base_pose'];T=np.eye(4);T[:3,:3]=Rotation.from_euler('z',b[2]).as_matrix();T[:2,3]=b[:2];return T

def ee(obs):
 T=frame(obs)@fk(obs['proprio']['arm_pos']);return T[:3,:3]@EE+T[:3,3],T[:3,:3]

def save(o,label='latest'):
 for k,v in o.get('images',{}).items():Image.fromarray(v).save('/app/output/'+label+'_'+k+'.png')
 np.savez('/app/output/'+label+'.npz',**{k:v for k,v in o.get('depth',{}).items()})
 json.dump({k:v for k,v in o.items() if k not in ['images','depth']},open('/app/output/'+label+'.json','w'))
 print('OBS',o['step'],o['done'],o['reason'],'base',np.round(o['proprio']['base_pose'],4),'q',np.round(o['proprio']['arm_pos'],4),'grip',o['proprio']['gripper_pos'],'EE',np.round(ee(o)[0],4),flush=True)

def ik(pos,R,q):
 def fun(a):
  T=fk(a);return np.r_[((T[:3,:3]@EE+T[:3,3])-pos)*5,Rotation.from_matrix(R.T@T[:3,:3]).as_rotvec()]
 lo=np.array([-100,-2.24,-100,-2.57,-100,-2.09,-100]);hi=-lo
 res=least_squares(fun,np.clip(q,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=300)
 if np.linalg.norm(fun(res.x))>.02:print('IK residual',fun(res.x),flush=True)
 return res.x

def move_q(q,grip=0,max_steps=100):
 o=r.observe(False)
 for i in range(max_steps):
  d=np.array(q)-o['proprio']['arm_pos']
  if max(abs(d))<.008:break
  o=r.step('delta',np.r_[0,0,0,np.clip(d,-.1,.1),grip].tolist(),images=False)
  if o['done']:break
 return o

def move(pos,R,grip=0):
 o=r.observe(False);B=frame(o);local=B[:3,:3].T@(np.array(pos)-B[:3,3]);rot=B[:3,:3].T@R
 return move_q(ik(local,rot,o['proprio']['arm_pos']),grip)

def base(x,y,yaw=0,grip=0):
 o=r.observe(False)
 for i in range(100):
  d=np.array([x,y,yaw])-o['proprio']['base_pose'];d[2]=(d[2]+np.pi)%(2*np.pi)-np.pi
  if max(abs(d))<.005:break
  d[:2]*=min(1,.09/(np.linalg.norm(d[:2])+1e-10));d[2]=np.clip(d[2],-.1,.1)
  o=r.step('delta',np.r_[d,np.zeros(7),grip].tolist(),False)
  if o['done']:break
 return o

def points(o,cam):
 c=S['cameras'][cam];T=frame(o)
 if cam=='robot_wrist':T=T@fk(o['proprio']['arm_pos'])
 p=c['pose'];C=T[:3,:3]@np.array(p['position_m'])+T[:3,3];F=T[:3,:3]@p['forward'];U=T[:3,:3]@p['up'];Rt=T[:3,:3]@p['right']
 h,w=c['hw'];f=h/2/np.tan(np.deg2rad(c['fovy_deg']/2));yy,xx=np.indices((h,w));rays=F+(xx[...,None]-(w-1)/2)/f*Rt-(yy[...,None]-(h-1)/2)/f*U
 if cam in o.get('depth',{}):d=o['depth'][cam]
 else:d=(.02-C[2])/rays[:,:,2]
 return C+rays*d[...,None]

def rods(o,cam):
 from scipy.ndimage import label
 im=o['images'][cam].astype(float);mask=(im[:,:,0]>55)&(im[:,:,0]>im[:,:,1]*1.35)&(im[:,:,1]>im[:,:,2]*1.2)&(im[:,:,1]<130)
 pts=points(o,cam);mask&=(pts[:,:,2]<.07)&(pts[:,:,2]>-.01)
 labs,n=label(mask);out=[]
 for i in range(1,n+1):
  ps=pts[labs==i]
  if len(ps)<60:continue
  center=(ps.min(0)+ps.max(0))/2
  _,_,v=np.linalg.svd(ps[:,:2]-ps[:,:2].mean(0),full_matrices=False)
  out.append((center.tolist(),np.arctan2(v[0,1],v[0,0]),len(ps)))
 return out
if __name__=='__main__':
 mode=sys.argv[1] if len(sys.argv)>1 else 'observe'
 if mode=='observe':
  o=r.observe();save(o);print('rods base',rods(o,'robot_base'));print('rods wrist',rods(o,'robot_wrist'))
 elif mode=='q':move_q(np.array(json.loads(sys.argv[2])),float(sys.argv[3]) if len(sys.argv)>3 else 0);save(r.observe())
 elif mode=='move':
  args=json.loads(sys.argv[2]);move(args['pos'],Rotation.from_euler('xyz',args['rot']).as_matrix(),args.get('grip',0));save(r.observe())
 elif mode=='base':
  base(*json.loads(sys.argv[2]));save(r.observe())
 elif mode=='grip':
  o=r.step('delta',[[0]*10+[float(sys.argv[2])]]*int(sys.argv[3]),True);save(o)
 elif mode=='reset':save(r.reset())
PY
