def planar(pos,yaw=0,qref=None):
 # Downward gripper, fixed elbow swivel; base-frame position and yaw.
 R=Rotation.from_euler('z',yaw).as_matrix()@Rotation.from_euler('y',np.pi).as_matrix()
 if qref is None:qref=np.array(r.observe(False)['proprio']['arm_pos'])
 def f(v):
  q=np.array([v[0],v[1],np.pi,v[2],0,v[3],v[4]]);T=fk(q)
  return np.r_[5*(T[:3,:3]@EE+T[:3,3]-pos),Rotation.from_matrix(R.T@T[:3,:3]).as_rotvec()]
 v=least_squares(f,qref[[0,1,3,5,6]],bounds=([-50,-2.24,-2.57,-2.09,-50],[50,2.24,2.57,2.09,50]),max_nfev=200).x
 return np.array([v[0],v[1],np.pi,v[2],0,v[3],v[4]])

def down(pos,yaw=0,grip=0):
 o=r.observe(False);B=frame(o);p=B[:3,:3].T@(np.array(pos)-B[:3,3]);return move_q(planar(p,yaw-o['proprio']['base_pose'][2]),grip)
